use std::collections::{BTreeMap,HashSet};use std::fs::File;use std::io::{self,Read};use std::path::Path;use crate::command::{CommandRejectReason,ExchangeEvent};use crate::order::{ClientOrderId,ExchangeOrderId};use crate::sequence::SequenceNumber;const MAGIC:&[u8;4]=b"SEJ1";const VERSION:u16=1;const HEADER_LEN:usize=32;
#[derive(Debug)]pub enum ReplayError{Io(io::Error),InvalidHeader(&'static str),InvalidRecord(&'static str),ChecksumMismatch{expected:u32,actual:u32},SequenceRegression{previous:u64,next:u64},UnsupportedVersion(u16),InvalidEventType(u8),InvalidPayload(&'static str)}impl From<io::Error> for ReplayError{fn from(e:io::Error)->Self{Self::Io(e)}}impl std::fmt::Display for ReplayError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self{Self::Io(e)=>write!(f,"replay I/O error: {e}"),Self::InvalidHeader(m)=>write!(f,"invalid journal header: {m}"),Self::InvalidRecord(m)=>write!(f,"invalid journal record: {m}"),Self::ChecksumMismatch{expected,actual}=>write!(f,"checksum mismatch: expected {expected:#x}, got {actual:#x}"),Self::SequenceRegression{previous,next}=>write!(f,"sequence regression: previous={previous}, next={next}"),Self::UnsupportedVersion(v)=>write!(f,"unsupported journal version {v}"),Self::InvalidEventType(v)=>write!(f,"invalid event type {v}"),Self::InvalidPayload(m)=>write!(f,"invalid event payload: {m}")}}}impl std::error::Error for ReplayError{}
#[derive(Debug,Clone,Copy,PartialEq,Eq,Hash,PartialOrd,Ord)]pub struct ReplayOrderKey{pub instrument_id:u16,pub account_id:u32,pub client_order_id:ClientOrderId}#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub struct ReplayTrade{pub instrument_id:u16,pub buyer_exchange_order_id:ExchangeOrderId,pub seller_exchange_order_id:ExchangeOrderId,pub buyer_client_order_id:ClientOrderId,pub seller_client_order_id:ClientOrderId,pub price:u32,pub qty:u32,pub buyer_sequence_number:SequenceNumber,pub seller_sequence_number:SequenceNumber,pub timestamp:u64}#[derive(Debug,Default)]pub struct ReplayLedger{pub event_count:u64,pub last_sequence:Option<u64>,pub accepted_orders:BTreeMap<ReplayOrderKey,ExchangeOrderId>,pub cancelled_orders:HashSet<ReplayOrderKey>,pub replaced_orders:u64,pub trades:Vec<ReplayTrade>}
impl ReplayLedger{pub fn apply(&mut self,event:&ExchangeEvent)->Result<(),ReplayError>{let sequence=event_sequence(event);if let Some(previous)=self.last_sequence{if sequence<previous{return Err(ReplayError::SequenceRegression{previous,next:sequence})}}match *event{ExchangeEvent::OrderAccepted{instrument_id,account_id,client_order_id,exchange_order_id,..}=>{let key=ReplayOrderKey{instrument_id,account_id,client_order_id};self.accepted_orders.insert(key,exchange_order_id);self.cancelled_orders.remove(&key);},ExchangeEvent::OrderRejected{..}=>{},ExchangeEvent::OrderCancelled{instrument_id,account_id,client_order_id,..}=>{let key=ReplayOrderKey{instrument_id,account_id,client_order_id};self.accepted_orders.remove(&key);self.cancelled_orders.insert(key);},ExchangeEvent::OrderReplaced{instrument_id,account_id,old_client_order_id,..}=>{let old=ReplayOrderKey{instrument_id,account_id,client_order_id:old_client_order_id};self.accepted_orders.remove(&old);self.cancelled_orders.insert(old);self.replaced_orders+=1;},ExchangeEvent::Trade{instrument_id,buyer_exchange_order_id,seller_exchange_order_id,buyer_client_order_id,seller_client_order_id,buyer_sequence_number,seller_sequence_number,price,qty,timestamp,..}=>self.trades.push(ReplayTrade{instrument_id,buyer_exchange_order_id,seller_exchange_order_id,buyer_client_order_id,seller_client_order_id,price,qty,buyer_sequence_number,seller_sequence_number,timestamp}),};self.event_count+=1;self.last_sequence=Some(sequence);Ok(())}pub fn can_reconstruct_book(&self)->bool{false}}
pub fn replay_file(path:impl AsRef<Path>)->Result<ReplayLedger,ReplayError>{let mut file=File::open(path)?;let mut bytes=Vec::new();file.read_to_end(&mut bytes)?;replay_bytes(&bytes)}pub fn replay_bytes(bytes:&[u8])->Result<ReplayLedger,ReplayError>{let mut offset=0;let mut ledger=ReplayLedger::default();while offset<bytes.len(){if bytes.len()-offset<HEADER_LEN{return Err(ReplayError::InvalidRecord("truncated header"))}let header=&bytes[offset..offset+HEADER_LEN];if &header[0..4]!=MAGIC{return Err(ReplayError::InvalidHeader("bad magic"))}let version=u16::from_le_bytes([header[4],header[5]]);if version!=VERSION{return Err(ReplayError::UnsupportedVersion(version))}let event_type=header[6];let sequence=u64::from_le_bytes(header[8..16].try_into().unwrap());let payload_len=u32::from_le_bytes(header[24..28].try_into().unwrap())as usize;let end=offset.checked_add(HEADER_LEN).and_then(|x|x.checked_add(payload_len)).ok_or(ReplayError::InvalidRecord("record length overflow"))?;if end>bytes.len(){return Err(ReplayError::InvalidRecord("truncated payload"))}let expected=u32::from_le_bytes(header[28..32].try_into().unwrap());let payload=&bytes[offset+HEADER_LEN..end];let actual=crc32(payload);if expected!=actual{return Err(ReplayError::ChecksumMismatch{expected,actual})}let event=decode_event(event_type,payload)?;if event_sequence(&event)!=sequence{return Err(ReplayError::InvalidRecord("header/event sequence mismatch"))}ledger.apply(&event)?;offset=end}Ok(ledger)}
fn event_sequence(event:&ExchangeEvent)->u64{match event{ExchangeEvent::OrderAccepted{sequence_number,..}|ExchangeEvent::OrderCancelled{sequence_number,..}|ExchangeEvent::OrderReplaced{sequence_number,..}=>sequence_number.0,ExchangeEvent::OrderRejected{sequence_number,..}=>sequence_number.map_or(0,|s|s.0),ExchangeEvent::Trade{buyer_sequence_number,seller_sequence_number,..}=>buyer_sequence_number.0.max(seller_sequence_number.0)}}fn decode_event(kind:u8,p:&[u8])->Result<ExchangeEvent,ReplayError>{let mut r=Reader{bytes:p,pos:0};match kind{1=>Ok(ExchangeEvent::OrderAccepted{instrument_id:r.u16()?,account_id:r.u32()?,client_order_id:ClientOrderId(r.u64()?),exchange_order_id:ExchangeOrderId(r.u64()?),sequence_number:SequenceNumber(r.u64()?)}),2=>Ok(ExchangeEvent::OrderRejected{account_id:r.u32()?,client_order_id:ClientOrderId(r.u64()?),sequence_number:{let s=r.u64()?;if s==0{None}else{Some(SequenceNumber(s))}},reason:decode_reason(r.u8()?)?}),3=>Ok(ExchangeEvent::OrderCancelled{instrument_id:r.u16()?,account_id:r.u32()?,client_order_id:ClientOrderId(r.u64()?),sequence_number:SequenceNumber(r.u64()?)}),4=>Ok(ExchangeEvent::OrderReplaced{instrument_id:r.u16()?,account_id:r.u32()?,old_client_order_id:ClientOrderId(r.u64()?),new_client_order_id:ClientOrderId(r.u64()?),exchange_order_id:ExchangeOrderId(r.u64()?),sequence_number:SequenceNumber(r.u64()?)}),5=>Ok(ExchangeEvent::Trade{buyer:r.u32()?,seller:r.u32()?,instrument_id:r.u16()?,buyer_exchange_order_id:ExchangeOrderId(r.u64()?),seller_exchange_order_id:ExchangeOrderId(r.u64()?),buyer_client_order_id:ClientOrderId(r.u64()?),seller_client_order_id:ClientOrderId(r.u64()?),buyer_sequence_number:SequenceNumber(r.u64()?),seller_sequence_number:SequenceNumber(r.u64()?),price:r.u32()?,qty:r.u32()?,timestamp:r.u64()?}),other=>Err(ReplayError::InvalidEventType(other))}}fn decode_reason(v:u8)->Result<CommandRejectReason,ReplayError>{match v{0=>Ok(CommandRejectReason::InvalidInstrument),1=>Ok(CommandRejectReason::InvalidSide),2=>Ok(CommandRejectReason::DuplicateClientOrderId),3=>Ok(CommandRejectReason::UnknownOrder),4=>Ok(CommandRejectReason::ExchangeOrderIdExhausted),5=>Ok(CommandRejectReason::SequenceNumberExhausted),6=>Ok(CommandRejectReason::OrderPoolExhausted),_=>Err(ReplayError::InvalidPayload("unknown rejection reason"))}}struct Reader<'a>{bytes:&'a[u8],pos:usize}impl<'a>Reader<'a>{fn take(&mut self,n:usize)->Result<&'a[u8],ReplayError>{let end=self.pos.checked_add(n).ok_or(ReplayError::InvalidPayload("offset overflow"))?;if end>self.bytes.len(){return Err(ReplayError::InvalidPayload("truncated payload"))}let out=&self.bytes[self.pos..end];self.pos=end;Ok(out)}fn u8(&mut self)->Result<u8,ReplayError>{Ok(self.take(1)?[0])}fn u16(&mut self)->Result<u16,ReplayError>{Ok(u16::from_le_bytes(self.take(2)?.try_into().unwrap()))}fn u32(&mut self)->Result<u32,ReplayError>{Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))}fn u64(&mut self)->Result<u64,ReplayError>{Ok(u64::from_le_bytes(self.take(8)?.try_into().unwrap()))}}fn crc32(bytes:&[u8])->u32{let mut crc=0xffff_ffffu32;for&byte in bytes{crc^=byte as u32;for _ in 0..8{crc=if crc&1!=0{(crc>>1)^0xedb8_8320}else{crc>>1}}}!crc}
